for path, cfg in files.items():
    text = path.read_text()
    for key in ('old_css', 'old_html'):
        if cfg[key] not in text:
            raise SystemExit(f'{key} not found in {path}')
    text = text.replace(cfg['old_css'], cfg['new_css'])
    text = text.replace(cfg['old_html'], cfg['new_html'])
    path.write_text(text)
    print(f'updated {path}')
